 13 export function planDigest(item, plan) {
 14   const definition = {
 15     id: item.id, type: item.type, revision: item.revision || 1, flags: item.flags,
 16     acceptance: item.input.acceptance, authorization: item.authorization,
 17     mode: plan.mode,
 18     tasks: plan.tasks.map((task) => ({
 19       id: task.id, title: task.title, owner: task.owner, risk: task.risk,
 20       blockedBy: task.blockedBy, writeScopes: task.writeScopes, docsImpact: task.docsImpact,
 21       checks: checksFor(task), reviewBatch: task.reviewBatch,
 22     })),
 23     reviewBatches: plan.reviewBatches,
 24   };
 25   return createHash("sha256").update(JSON.stringify(definition)).digest("hex");
 26 }
