 28 export async function readEvidence(root, id) {
 29   const config = await readJson(path.join(root, ".ai-harness/config.json"));
 30   const file = await resolveProjectPath(root, `${config.workItemsDirectory}/${id}/evidence.jsonl`);
 31   let raw;
 32   try { raw = await readFile(file, "utf8"); } catch (error) {
 33     if (error.code === "ENOENT") return [];
 34     throw error;
 35   }
 36   return raw.split(/\r?\n/).flatMap((line, index) => {
 37     if (!line.trim()) return [];
 38     let event;
 39     try { event = JSON.parse(line); } catch { invariant(false, "INVALID_EVIDENCE_JSONL", `证据第 ${index + 1} 行不是有效 JSON。`); }
 40     invariant(event.workItemId === id, "INVALID_EVIDENCE_OWNER", "证据归属与工作项不一致。" );
 41     return [event];
 42   });
 43 }
