 45 export function matchingChecks(plan, taskId, command, args) {
 46   const key = commandKey(command, args);
 47   return plan.tasks.filter((task) => (!taskId || task.id === taskId) && task.status !== "DEFERRED")
 48     .flatMap((task) => checksFor(task).filter((check) => commandKey(check.command, check.args) === key).map((check) => ({ taskId: task.id, checkId: check.id })));
 49 }
