 51 export async function verificationReport(root, item, plan, { taskId = null, snapshot = null, events = null } = {}) {
 52   const current = snapshot || await sourceSnapshot(root);
 53   const evidence = events || await readEvidence(root, item.id);
 54   const digest = planDigest(item, plan);
 55   const latest = new Map();
 56   for (const event of evidence) {
 57     if (event.kind !== "command" || (event.revision || 1) !== (item.revision || 1) || !event.command || (taskId && event.taskId !== taskId)) continue;
 58     const task = plan.tasks.find((candidate) => candidate.id === event.taskId);
 59     if (task && (event.taskAttempt || 1) !== (task.attempt || 1)) continue;
 60     latest.set(JSON.stringify([event.taskId, commandKey(event.command.executable, event.command.args)]), event);
 61   }
 62   let failed = [...latest.values()].filter((event) =>
 63     event.command.planDigest === digest &&
 64     (event.command.source?.digest === current.digest || event.command.sourceAfter?.digest === current.digest) &&
 65     event.status !== "pass");
 66   const successful = [...latest.values()].filter((event) =>
 67     event.status === "pass" && event.command.exitCode === 0 && !event.command.timedOut && !event.command.spawnError && !event.command.signal &&
 68     event.command.planDigest === digest && event.command.source?.digest === current.digest && event.command.sourceAfter?.digest === current.digest);
 69   const required = plan.tasks.filter((task) => (!taskId || task.id === taskId) && task.status !== "DEFERRED")
 70     .flatMap((task) => checksFor(task).map((check) => ({ taskId: task.id, ...check })));
 71   const positions = new Map(evidence.map((event, index) => [event.id, index]));
 72   failed = failed.filter((event) => !successful.some((later) => positions.get(later.id) > positions.get(event.id) &&
 73     commandKey(later.command.executable, later.command.args) === commandKey(event.command.executable, event.command.args) &&
 74     (!later.taskId || later.taskId === event.taskId)));
 75   const missing = required.filter((check) => !successful.some((event) =>
 76     commandKey(event.command.executable, event.command.args) === commandKey(check.command, check.args) &&
 77     (!event.taskId || event.taskId === check.taskId)));
 78   return { ok: required.length > 0 && missing.length === 0 && failed.length === 0, current, planDigest: digest, successful, missing, failed };
 79 }
