 81 export async function assertVerification(root, item, plan, options = {}) {
 82   const report = await verificationReport(root, item, plan, options);
 83   invariant(report.ok, "VERIFICATION_NOT_CURRENT", "计划中的验证尚未针对当前代码全部通过，或存在新的失败。", {
 84     missing: report.missing.map((check) => ({ taskId: check.taskId, checkId: check.id, command: check.command, args: check.args })),
 85     failed: report.failed.map((event) => event.id),
 86   });
 87   for (const event of report.successful) {
 88     await loadSnapshot(root, event.command.source);
 89     await loadSnapshot(root, event.command.sourceAfter);
 90   }
 91   return report;
 92 }
