 94 export async function assertCommandEvidence(root, item, plan, commandId, options = {}) {
 95   const report = await verificationReport(root, item, plan, options);
 96   const event = report.successful.find((candidate) => candidate.id === commandId);
 97   invariant(event && matchingChecks(plan, event.taskId, event.command.executable, event.command.args).length > 0, "COMMAND_EVIDENCE_INVALID", "命令证据必须匹配计划验证、当前代码和计划版本。" );
 98   await loadSnapshot(root, event.command.source);
 99   await loadSnapshot(root, event.command.sourceAfter);
100   return event;
101 }
