103 export function invalidateResults(item, plan, taskId = null) {
104   item.verification = { status: "pending", evidence: [], stages: [] };
105   item.review = { status: "pending", evidence: [], independent: false };
106   item.acceptance = { status: "pending", evidence: [] };
107   item.delivery = null;
108   if (taskId) {
109     const task = plan.tasks.find((candidate) => candidate.id === taskId);
110     if (task?.status === "IN_PROGRESS") {
111       task.verificationStatus = "pending";
112       task.reviewStatus = "pending";
113     }
114   }
115 }

