20 function gitQuotedPath(file) {
21   return '"' + file.replace(/[\x00-\x1f\x7f"\\]/g, (char) => char === '"' || char === "\\" ? `\\${char}` : `\\${char.charCodeAt(0).toString(8).padStart(3, "0")}`) + '"';
