24 export async function sourceSnapshot(root) {
25   const config = await readJson(path.join(root, ".ai-harness/config.json"));
26   const index = gitResult(root, ["ls-files", "--stage", "-z"]).stdout.split("\0").filter(Boolean);
27   const files = Object.create(null);
28   for (const entry of index) {
29     const match = /^(\d+) ([0-9a-f]+) (\d)\t([\s\S]+)$/.exec(entry);
30     invariant(match && match[3] === "0", "UNMERGED_SOURCE", "代码快照包含未解决的合并冲突。" );
31     if (!controlPath(match[4], config.workItemsDirectory)) files[match[4]] = `${match[1]}:${match[2]}`;
32   }
33   const modified = gitResult(root, ["diff", "--name-only", "-z", "--no-renames", "--ignore-submodules=none"]).stdout.split("\0").filter(Boolean);
34   const untracked = gitResult(root, ["ls-files", "--others", "--exclude-standard", "-z"]).stdout.split("\0").filter(Boolean);
35   const regular = [];
36   const fileMode = gitResult(root, ["config", "--bool", "core.filemode"], { allowFailure: true }).stdout.trim() !== "false";
37   for (const file of [...new Set([...modified, ...untracked])].sort()) {
38     if (controlPath(file, config.workItemsDirectory)) continue;
39     const absolute = await resolveProjectPath(root, file);
40     let info;
41     try { info = await lstat(absolute); } catch (error) {
42       if (error.code === "ENOENT") { delete files[file]; continue; }
43       throw error;
44     }
45     invariant(!files[file]?.startsWith("160000:"), "DIRTY_SUBMODULE", `子模块有未冻结的变更，需先记录其提交：${file}`);
46     if (info.isSymbolicLink()) {
47       const oid = gitResult(root, ["hash-object", "--stdin"], { input: await readlink(absolute) }).stdout.trim();
48       files[file] = `120000:${oid}`;
49     } else {
50       invariant(info.isFile(), "UNSUPPORTED_SOURCE_FILE", `不能对非普通文件建立代码快照：${file}`);
51       regular.push({ file, mode: fileMode ? (info.mode & 0o111 ? "100755" : "100644") : (files[file]?.split(":")[0] || "100644") });
52     }
53   }
54   if (regular.length) {
55     const hashes = gitResult(root, ["hash-object", "--stdin-paths"], { input: regular.map(({ file }) => gitQuotedPath(file)).join("\n") + "\n" }).stdout.trim().split(/\r?\n/);
56     invariant(hashes.length === regular.length && hashes.every((oid) => /^[0-9a-f]{40,64}$/.test(oid)), "SNAPSHOT_HASH_FAILED", "Git 未返回完整的代码内容标识。" );
57     regular.forEach(({ file, mode }, index) => { files[file] = `${mode}:${hashes[index]}`; });
58   }
59   return makeSnapshot(files);
60 }
