62 export async function commitSnapshot(root, commit) {
63   invariant(/^[0-9a-f]{40,64}$/.test(commit || ""), "INVALID_SNAPSHOT_COMMIT", "代码快照需要完整提交标识。" );
64   const config = await readJson(path.join(root, ".ai-harness/config.json"));
65   const files = Object.create(null);
66   for (const entry of gitResult(root, ["ls-tree", "-r", "-z", commit]).stdout.split("\0").filter(Boolean)) {
67     const match = /^(\d+) (blob|commit) ([0-9a-f]+)\t([\s\S]+)$/.exec(entry);
68     invariant(match, "INVALID_GIT_TREE", "提交包含无法识别的文件条目。" );
69     if (!controlPath(match[4], config.workItemsDirectory)) files[match[4]] = `${match[1]}:${match[3]}`;
70   }
71   return makeSnapshot(files);
72 }
