84 export async function loadSnapshot(root, reference) {
85   invariant(reference && /^[0-9a-f]{64}$/.test(reference.digest || "") && typeof reference.document === "string", "SNAPSHOT_REQUIRED", "缺少可验证的代码快照引用。" );
86   const snapshot = await readJson(await resolveProjectPath(root, reference.document, { mustExist: true }));
87   invariant(snapshot.version === 1 && snapshot.files && typeof snapshot.files === "object" && !Array.isArray(snapshot.files), "INVALID_SNAPSHOT", "代码快照结构无效。" );
88   for (const [file, value] of Object.entries(snapshot.files)) {
