45 export async function collectScopeErrors(root, records, items) {
46   const config = await readJson(path.join(root, ".ai-harness/config.json"));
47   const current = await sourceSnapshot(root);
48   const errors = [];
49   const warnings = [];
50   const active = records.filter(({ item }) => item.status !== "DONE");
51   const activeScopes = [...new Set(active.flatMap(({ item, plan }) => plannedScopes(item, plan)))];
52   const archives = [];
53   for (const { item, plan } of records.filter(({ item }) => item.status === "DONE")) {
54     try {
55       if (!item.delivery) {
56         invariant(!item.integrityVersion, "DELIVERY_REQUIRED", `工作项 ${item.id} 缺少交付快照。`);
57         archives.push({ item, scopes: [], ...await legacyArchive(root, item, config) });
58         continue;
59       }
60       invariant(item.delivery.planDigest === planDigest(item, plan), "DELIVERY_PLAN_CHANGED", `工作项 ${item.id} 的交付计划已改变。`);
61       const source = await loadSnapshot(root, item.delivery.source);
62       const baseline = await loadSnapshot(root, item.delivery.baseline);
63       const scopes = plannedScopes(item, plan);
64       for (const file of snapshotChanges(baseline, source)) {
65         if (!scopes.some((scope) => fileMatchesScope(file, scope))) errors.push(`${item.id}: 交付变更超出其批准范围：${file}`);
66       }
67       archives.push({ item, source, scopes, at: item.delivery.at, legacy: false });
68     } catch (error) { errors.push(error.message); }
69   }
70   const controls = items.map((item) => `${config.workItemsDirectory}/${item.id}/**`);
71   let frontier = archives.toSorted((left, right) => left.at.localeCompare(right.at)).at(-1)?.source;
72   if (!frontier) {
73     const first = active.toSorted((left, right) => left.item.baseline.completedAt.localeCompare(right.item.baseline.completedAt))[0];
74     frontier = first ? await baselineSnapshot(root, first.item, current, config)
75       : await commitSnapshot(root, gitResult(root, ["rev-parse", "HEAD"]).stdout.trim());
76   }
77   const changed = new Set(snapshotChanges(frontier, current));
78   for (const file of changed) {
79     if (!activeScopes.some((scope) => fileMatchesScope(file, scope))) errors.push(`当前变更没有活动工作项授权，历史完成范围不能复用：${file}`);
80   }
81   for (const { item } of active) {
82     const baseline = await baselineSnapshot(root, item, current, config);
83     for (const file of snapshotChanges(baseline, current)) {
84       changed.add(file);
85       const completedSinceBaseline = archives.some((archive) => !archive.legacy && archive.at >= item.baseline.completedAt &&
86         archive.source.files[file] === current.files[file] && archive.scopes.some((scope) => fileMatchesScope(file, scope)));
87       if (!completedSinceBaseline && !activeScopes.some((scope) => fileMatchesScope(file, scope))) errors.push(`当前工作变更超出批准范围：${file}`);
88     }
89   }
90   return { errors: [...new Set(errors)], warnings, changedFiles: [...changed].sort(), scopes: [...new Set([...activeScopes, ...controls])].sort() };
91 }

