66 export async function resolveCommandLaunch(command, args, { platform = process.platform, searchPath = process.env.PATH || process.env.Path || "" } = {}) {
67   const name = commandName(command);
68   const entries = {
69     npm: ["node_modules/npm/bin/npm-cli.js"],
70     pnpm: ["node_modules/pnpm/bin/pnpm.cjs", "node_modules/corepack/dist/pnpm.js"],
71     yarn: ["node_modules/yarn/bin/yarn.js", "node_modules/corepack/dist/yarn.js"],
