73   if (platform !== "win32" || !entries[name]) return { command, args: [...args] };
74   const directories = [...new Set(searchPath.split(platform === "win32" ? ";" : path.delimiter).filter(Boolean).concat(path.dirname(process.execPath)))];
75   for (const directory of directories) {
