 23 function parseStageInput(entries, allowed, option) {
 24   invariant(Array.isArray(entries), "STAGE_INPUT_INVALID", `${option} 必须是 stage=value 数组。`);
 25   const values = new Map();
 26   for (const entry of entries) {
 27     const separator = typeof entry === "string" ? entry.indexOf("=") : -1;
 28     invariant(separator > 0, "STAGE_INPUT_INVALID", `${option} 格式必须为 stage=value。`);
 29     const stage = entry.slice(0, separator).trim();
 30     const value = entry.slice(separator + 1).trim();
 31     invariant(allowed.includes(stage) && value && !values.has(stage), "STAGE_INPUT_INVALID", `${option} 包含不适用、重复或空的阶段：${stage}`);
 32     values.set(stage, value);
 33   }
 34   return values;
 35 }
