161 export function collectPlanErrors(plan, workItemId = null, { requireComplete = true } = {}) {
162   const errors = [];
163   if (!isObject(plan)) return ["计划必须是 JSON 对象。"];
164   if (plan.schemaVersion !== 1) errors.push("计划 schemaVersion 必须为 1。");
