178       continue;
179     }
180     if (tasksById.has(task.id)) errors.push(`重复任务 ID：${task.id}`);
181     tasksById.set(task.id, task);
182     if (!task.title?.trim()) errors.push(`${task.id} 标题不能为空。`);
183     if (!task.module?.trim()) errors.push(`${task.id} module 不能为空。`);
184     if (!TASK_STATUSES.includes(task.status)) errors.push(`${task.id} 状态无效：${task.status}`);
185     if (!Array.isArray(task.blockedBy) || !Array.isArray(task.blocks)) errors.push(`${task.id} 依赖字段必须是数组。`);
186     if (!nonEmptyStrings(task.writeScopes)) errors.push(`${task.id} 至少需要一个写入范围。`);
187     else if (task.writeScopes.some((scope) => !scopeValid(scope))) errors.push(`${task.id} 包含过宽或越界写入范围。`);
188     if (!nonEmptyStrings(task.verification)) errors.push(`${task.id} 至少需要一个验证方式。`);
189     else if (task.checks !== undefined) {
190       try {
191         if (JSON.stringify(task.checks) !== JSON.stringify(compileChecks(task.verification))) errors.push(`${task.id} checks 与验证声明不一致。`);
192       } catch { errors.push(`${task.id} 验证声明无法编译为命令。`); }
193     }
194     if (task.attempt !== undefined && (!Number.isInteger(task.attempt) || task.attempt < 0)) errors.push(`${task.id} attempt 无效。`);
195     for (const name of ["verificationSource", "reviewSource"]) if (task[name] !== undefined && !validSource(task[name])) errors.push(`${task.id}.${name} 无效。`);
196     if (!nonEmptyStrings(task.docsImpact)) errors.push(`${task.id} 必须记录文档影响或 N/A: 理由。`);
197     if (!task.reviewBatch?.trim()) errors.push(`${task.id} 必须属于 Review Batch。`);
198     if (!['low', 'medium', 'high'].includes(task.risk)) errors.push(`${task.id} 风险等级无效。`);
199     if (!task.owner?.trim()) errors.push(`${task.id} owner 不能为空。`);
200     if (!RESULT_STATUSES.includes(task.verificationStatus)) errors.push(`${task.id} verificationStatus 无效。`);
201     if (!RESULT_STATUSES.includes(task.reviewStatus)) errors.push(`${task.id} reviewStatus 无效。`);
202     if (!Array.isArray(task.evidence)) errors.push(`${task.id} evidence 必须是数组。`);
203     if (["IMPLEMENTED", "IN_REVIEW", "COMPLETED"].includes(task.status) && task.verificationStatus !== "pass") {
204       errors.push(`${task.id} 在 ${task.status} 前必须通过任务验证。`);
205     }
