393     invariant(unfinished.length === 0, "TASKS_UNFINISHED", "仍有任务未完成或未获批准延期。", {
394       tasks: unfinished.map((task) => `${task.id}:${task.status}`),
395     });
396     return;
397   }
398   if (target === "CODE_REVIEW") {
