416     const independentRequired = plan?.reviewBatches?.some((batch) => batch.independentRequired) || false;
417     invariant(!independentRequired || item.review.independent, "INDEPENDENT_REVIEW_REQUIRED", "高风险批次需要独立复核证据。" );
418     if (!(item.status === "DONE" && !item.integrityVersion)) {
419       const snapshot = item.status === "DONE" ? await loadSnapshot(root, item.delivery?.source) : await sourceSnapshot(root);
420       await assertVerification(root, item, plan, { snapshot });
421       invariant(item.review.source?.digest === snapshot.digest, "STALE_REVIEW", "审查结论不对应当前待交付代码。" );
422     }
423     return;
424   }
425   if (target === "DONE") {
426     invariant(item.acceptance.status === "pass" && nonEmptyStrings(item.acceptance.evidence), "ACCEPTANCE_REQUIRED", "DONE 前缺少有权验收证据。" );
427     if (!(item.status === "DONE" && !item.integrityVersion)) {
428       const snapshot = item.status === "DONE" ? await loadSnapshot(root, item.delivery?.source) : await sourceSnapshot(root);
429       await assertVerification(root, item, plan, { snapshot });
430       invariant(item.review.source?.digest === snapshot.digest && item.acceptance.source?.digest === snapshot.digest, "STALE_ACCEPTANCE", "验收和审查必须对应同一待交付代码版本。" );
431     }
432     return;
433   }
434   if (target === "ANSWERED") {
435     invariant(item.type === "ANALYSIS", "TYPE_MISMATCH", "只有 ANALYSIS 可以进入 ANSWERED。" );
436     invariant(item.analysis.status === "pass", "ANALYSIS_INCOMPLETE", "分析回答尚未标记通过。" );
437     invariant(item.analysis.conclusions.length > 0, "ANALYSIS_CONCLUSION_REQUIRED", "至少需要一个带状态的分析结论。" );
438     for (const conclusion of item.analysis.conclusions) {
439       invariant(CONCLUSION_STATUSES.includes(conclusion.status), "ANALYSIS_STATUS_INVALID", "分析结论状态无效。", { conclusion });
440       invariant(conclusion.text?.trim(), "ANALYSIS_TEXT_REQUIRED", "分析结论不能为空。" );
441       if (conclusion.status !== "UNKNOWN") {
442         invariant(nonEmptyStrings(conclusion.evidence), "ANALYSIS_EVIDENCE_REQUIRED", `${conclusion.status} 结论缺少证据。`);
443       }
444     }
445   }
