448 export function collectHistoryErrors(item) {
449   const errors = [];
450   if (!Array.isArray(item.history) || item.history.length === 0) return ["状态历史为空。"];
451   let previous = null;
452   for (let index = 0; index < item.history.length; index += 1) {
453     const entry = item.history[index];
454     if (entry.from !== previous) errors.push(`history[${index}] from 与前一状态不一致。`);
455     if (!WORK_STATUSES.includes(entry.to)) errors.push(`history[${index}] 目标状态无效。`);
456     if (entry.to !== "BLOCKED" && entry.from !== "BLOCKED" && entry.from !== null) {
457       const allowed = BASE_TRANSITIONS[item.type]?.[entry.from] || [];
458       const recovery = ["reopen", "replan"].includes(entry.action) && entry.reason?.trim() && entry.revision > 1 &&
459         ["IMPLEMENTING", "VERIFYING", "CODE_REVIEW", "READY_FOR_ACCEPTANCE", "DONE"].includes(entry.from) &&
460         entry.to === (entry.action === "replan" ? "SOLUTION_DESIGN" : "IMPLEMENTING");
461       if (!allowed.includes(entry.to) && !recovery) errors.push(`history[${index}] 包含非法转换 ${entry.from} -> ${entry.to}。`);
462     }
463     if (entry.to === "BLOCKED" && !entry.reason?.trim()) errors.push(`history[${index}] 阻塞缺少原因。`);
464     if (entry.from === "BLOCKED" && entry.to !== entry.unblockedTo) errors.push(`history[${index}] 解除阻塞目标记录无效。`);
465     previous = entry.to;
466   }
467   if (previous !== item.status) errors.push("当前状态与历史最后状态不一致。");
468   return errors;
469 }
