471 export async function collectProgressErrors(root, item, plan, { allowStale = false } = {}) {
472   const errors = [...collectWorkItemShapeErrors(item), ...collectHistoryErrors(item)];
473   if (item.status === "BLOCKED") return [...new Set(errors)];
474   const addGateError = async (target) => {
475     try {
476       await assertTransitionGates(root, item, plan, target);
477     } catch (error) {
478       if (allowStale && ["VERIFICATION_NOT_CURRENT", "STALE_VERIFICATION", "STALE_REVIEW", "STALE_ACCEPTANCE"].includes(error.code)) return;
479       errors.push(`${target}: ${error.message}`);
480       if (error.details?.errors) errors.push(...error.details.errors.map((detail) => `${target}: ${detail}`));
481     }
482   };
483 
484   if (item.type === "ANALYSIS") {
485     if (["ANALYZING", "ANSWERED"].includes(item.status)) await addGateError("ANALYZING");
486     if (item.status === "ANSWERED") await addGateError("ANSWERED");
487     return [...new Set(errors)];
488   }
489 
490   const reached = (statuses) => statuses.includes(item.status);
491   if (reached(["SOLUTION_DESIGN", "DATABASE_DESIGN", "PLANNED", "IMPLEMENTING", "VERIFYING", "CODE_REVIEW", "READY_FOR_ACCEPTANCE", "DONE"])) {
492     await addGateError("SOLUTION_DESIGN");
493   }
494   if (reached(["PLANNED", "IMPLEMENTING", "VERIFYING", "CODE_REVIEW", "READY_FOR_ACCEPTANCE", "DONE"])) {
495     await addGateError("PLANNED");
496   }
497   if (reached(["IMPLEMENTING", "VERIFYING", "CODE_REVIEW", "READY_FOR_ACCEPTANCE", "DONE"])) await addGateError("IMPLEMENTING");
498   if (reached(["VERIFYING", "CODE_REVIEW", "READY_FOR_ACCEPTANCE", "DONE"])) await addGateError("VERIFYING");
499   if (reached(["CODE_REVIEW", "READY_FOR_ACCEPTANCE", "DONE"])) await addGateError("CODE_REVIEW");
500   if (reached(["READY_FOR_ACCEPTANCE", "DONE"])) await addGateError("READY_FOR_ACCEPTANCE");
501   if (item.status === "DONE") await addGateError("DONE");
502   return [...new Set(errors)];
503 }
