116   if (executable === "dotnet") return ["test", "build", "format"].includes(normalizedArgs[0]);
117   if (executable === "flutter") return ["test", "analyze", "build"].includes(normalizedArgs[0]);
118   if (executable === "dart") return ["test", "analyze", "format", "compile"].includes(normalizedArgs[0]);
