127 export function classifyCommand(command, args = [], config = {}) {
128   if (typeof command !== "string" || !command.trim() || !Array.isArray(args) || !args.every((arg) => typeof arg === "string")) {
129     return { decision: "deny", rule: "parse-failure", reason: "命令或参数结构无效。" };
130   }
131   const executable = executableName(command);
132   const deny = new Set([...DEFAULT_DENY_EXECUTABLES, ...(config.additionalDenyExecutables || []).map((item) => item.toLowerCase())]);
133   const ask = new Set((config.additionalAskExecutables || []).map((item) => item.toLowerCase()));
134   const allow = new Set([...DEFAULT_ALLOW_EXECUTABLES, ...(config.additionalAllowExecutables || []).map((item) => item.toLowerCase())]);
135   const text = commandText(command, args);
136 
137   if (deny.has(executable)) {
138     return { decision: "deny", rule: "deny-executable", reason: `禁止通过 Harness 执行 ${executable}。` };
139   }
140   if (usesExplicitPath(command) && path.resolve(command) !== path.resolve(process.execPath)) {
141     return { decision: "ask", rule: "explicit-executable-path", reason: "显式可执行文件路径需要外部确认，避免同名程序伪装。" };
142   }
143   const deniedPattern = DENY_TEXT_PATTERNS.find((pattern) => pattern.test(text));
144   if (deniedPattern) {
145     return { decision: "deny", rule: "deny-structure", reason: "命令匹配不可逆或破坏性结构。" };
146   }
147   const askPattern = ASK_TEXT_PATTERNS.find((pattern) => pattern.test(text));
148   if (ask.has(executable) || askPattern) {
149     return { decision: "ask", rule: "external-approval", reason: "命令会修改依赖、Git、部署或外部状态，需要在 Harness 外取得明确授权。" };
150   }
151   if (!allow.has(executable)) {
152     return { decision: "ask", rule: "unknown-executable", reason: `未知可执行文件 ${executable}，默认不执行。` };
153   }
154   if (!allowKnownSubcommand(executable, args)) {
155     return { decision: "ask", rule: "unknown-subcommand", reason: `${executable} 子命令不在验证型允许范围内。` };
156   }
157   return { decision: "allow", rule: "verified-command", reason: "命令属于允许的构建、检查或测试范围。" };
158 }

