272 export async function checkProject(root, { ci = false } = {}) {
273   const doctor = await doctorProject(root, { requireInitialized: true });
274   const errors = [...doctor.errors];
275   const warnings = [...doctor.warnings];
276   const config = await loadConfig(root);
277   const policyIndex = await readJson(path.join(root, ".ai-harness", "policies", "index.json"));
278   const records = [];
279   const items = [];
280   for (const id of await workItemIds(root, config)) {
281     try {
282       const item = await loadWorkItem(root, id);
283       items.push(item);
284       const expectedPolicies = expectedPolicyFiles(policyIndex, item);
285       if (JSON.stringify(item.policyFiles) !== JSON.stringify(expectedPolicies)) {
286         errors.push(`${id}: policyFiles 与工作类型/flags 的确定性路由不一致。`);
287       }
288       const plan = await loadPlan(root, id, { optional: true });
289       const progressErrors = await validateWorkItem(root, id);
290       errors.push(...progressErrors.map((message) => `${id}: ${message}`));
291       const evidenceErrors = await collectEvidenceErrors(root, item, plan);
292       errors.push(...evidenceErrors.map((message) => `${id}: ${message}`));
293       if (plan) {
294         const planErrors = collectPlanErrors(plan, id, { requireComplete: item.plan.approved || stateRequiresCompletePlan(item.status) });
295         errors.push(...planErrors.map((message) => `${id}: ${message}`));
296       }
297       if (["IMPLEMENTING", "VERIFYING", "CODE_REVIEW", "READY_FOR_ACCEPTANCE", "DONE"].includes(item.status)) {
298         records.push({ item, plan });
299       }
300     } catch (error) {
301       errors.push(`${id}: ${error.message}`);
302       if (error.details?.errors) errors.push(...error.details.errors.map((message) => `${id}: ${message}`));
303     }
304   }
305   const scope = await collectScopeErrors(root, records, items);
306   errors.push(...scope.errors);
307   warnings.push(...scope.warnings);
308   if (ci) {
309     const incomplete = items.filter((item) => !TERMINAL_STATUSES.includes(item.status));
310     if (incomplete.length > 0) {
311       errors.push(`CI 不接受未完成工作项：${incomplete.map((item) => `${item.id}:${item.status}`).join(", ")}`);
312     }
313   }
314   return {
315     ok: errors.length === 0,
316     errors: [...new Set(errors)],
317     warnings: [...new Set(warnings)],
318     details: {
319       ...doctor.details,
320       workItems: await workItemIds(root, config),
321       changedFiles: scope.changedFiles,
322       allowedScopes: scope.scopes,
323     },
324   };
325 }

