176     if (!isObject(task) || !WORK_ID_PATTERN.test(task.id || "")) {
177       errors.push("任务 ID 无效。");
178       continue;
179     }
180     if (tasksById.has(task.id)) errors.push(`重复任务 ID：${task.id}`);
181     tasksById.set(task.id, task);
182     if (!task.title?.trim()) errors.push(`${task.id} 标题不能为空。`);
183     if (!task.module?.trim()) errors.push(`${task.id} module 不能为空。`);
184     if (!TASK_STATUSES.includes(task.status)) errors.push(`${task.id} 状态无效：${task.status}`);
185     if (!Array.isArray(task.blockedBy) || !Array.isArray(task.blocks)) errors.push(`${task.id} 依赖字段必须是数组。`);
186     if (!nonEmptyStrings(task.writeScopes)) errors.push(`${task.id} 至少需要一个写入范围。`);
187     else if (task.writeScopes.some((scope) => !scopeValid(scope))) errors.push(`${task.id} 包含过宽或越界写入范围。`);
188     if (!nonEmptyStrings(task.verification)) errors.push(`${task.id} 至少需要一个验证方式。`);
189     else if (task.checks !== undefined) {
190       try {
191         if (JSON.stringify(task.checks) !== JSON.stringify(compileChecks(task.verification))) errors.push(`${task.id} checks 与验证声明不一致。`);
192       } catch { errors.push(`${task.id} 验证声明无法编译为命令。`); }
193     }
194     if (task.attempt !== undefined && (!Number.isInteger(task.attempt) || task.attempt < 0)) errors.push(`${task.id} attempt 无效。`);
195     for (const name of ["verificationSource", "reviewSource"]) if (task[name] !== undefined && !validSource(task[name])) errors.push(`${task.id}.${name} 无效。`);
196     if (!nonEmptyStrings(task.docsImpact)) errors.push(`${task.id} 必须记录文档影响或 N/A: 理由。`);
197     if (!task.reviewBatch?.trim()) errors.push(`${task.id} 必须属于 Review Batch。`);
198     if (!['low', 'medium', 'high'].includes(task.risk)) errors.push(`${task.id} 风险等级无效。`);
199     if (!task.owner?.trim()) errors.push(`${task.id} owner 不能为空。`);
200     if (!RESULT_STATUSES.includes(task.verificationStatus)) errors.push(`${task.id} verificationStatus 无效。`);
201     if (!RESULT_STATUSES.includes(task.reviewStatus)) errors.push(`${task.id} reviewStatus 无效。`);
202     if (!Array.isArray(task.evidence)) errors.push(`${task.id} evidence 必须是数组。`);
203     if (["IMPLEMENTED", "IN_REVIEW", "COMPLETED"].includes(task.status) && task.verificationStatus !== "pass") {
204       errors.push(`${task.id} 在 ${task.status} 前必须通过任务验证。`);
205     }
206     if (task.status === "COMPLETED" && task.reviewStatus !== "pass") {
207       errors.push(`${task.id} 标记 COMPLETED 前必须通过 Code Review。`);
208     }
209     if (task.status === "DEFERRED" && !task.deferralApproval?.trim()) {
210       errors.push(`${task.id} 延期缺少有权批准记录。`);
211     }
212   }
213 
214   for (const task of plan.tasks) {
215     for (const dependency of task.blockedBy || []) {
216       if (!tasksById.has(dependency)) errors.push(`${task.id} 依赖不存在：${dependency}`);
217       if (dependency === task.id) errors.push(`${task.id} 不能依赖自身。`);
218       const parent = tasksById.get(dependency);
219       if (parent && !parent.blocks.includes(task.id)) errors.push(`${dependency}.blocks 缺少 ${task.id}。`);
220     }
221     for (const blocked of task.blocks || []) {
222       if (!tasksById.has(blocked)) errors.push(`${task.id} blocks 指向不存在任务：${blocked}`);
223       const child = tasksById.get(blocked);
224       if (child && !child.blockedBy.includes(task.id)) errors.push(`${blocked}.blockedBy 缺少 ${task.id}。`);
225     }
226     if (["READY", "IN_PROGRESS", "IMPLEMENTED", "IN_REVIEW", "COMPLETED"].includes(task.status)) {
227       const incomplete = (task.blockedBy || []).filter((id) => !["COMPLETED", "DEFERRED"].includes(tasksById.get(id)?.status));
228       if (incomplete.length > 0) errors.push(`${task.id} 已解锁但依赖未完成：${incomplete.join(", ")}`);
229     }
230   }
231 
232   for (const task of plan.tasks) {
233     if (dependencyReachable(tasksById, task.id, task.id, new Set(["__start__"]))) {
234       const actualCycle = task.blocks.some((next) => dependencyReachable(tasksById, next, task.id));
235       if (actualCycle) errors.push(`任务依赖存在环：${task.id}`);
236     }
237   }
238 
239   const batchesById = new Map();
240   const membership = new Map();
241   for (const batch of plan.reviewBatches) {
242     if (!isObject(batch) || !WORK_ID_PATTERN.test(batch.id || "")) {
243       errors.push("Review Batch ID 无效。");
244       continue;
245     }
246     if (batchesById.has(batch.id)) errors.push(`重复 Review Batch：${batch.id}`);
247     batchesById.set(batch.id, batch);
248     if (!batch.title?.trim()) errors.push(`${batch.id} 标题不能为空。`);
249     if (!['low', 'medium', 'high'].includes(batch.risk)) errors.push(`${batch.id} 风险无效。`);
250     if (!Array.isArray(batch.taskIds) || (requireComplete && batch.taskIds.length === 0)) errors.push(`${batch.id} 必须包含任务。`);
251     if (typeof batch.independentRequired !== "boolean") errors.push(`${batch.id} independentRequired 必须是布尔值。`);
252     if (batch.risk === "high" && !batch.independentRequired) errors.push(`${batch.id} 为高风险，必须要求独立复核。`);
253     for (const taskId of batch.taskIds || []) {
254       if (!tasksById.has(taskId)) errors.push(`${batch.id} 包含不存在任务：${taskId}`);
255       if (membership.has(taskId)) errors.push(`${taskId} 同时属于多个 Review Batch。`);
256       membership.set(taskId, batch.id);
257     }
258   }
259   for (const task of plan.tasks) {
260     if (!batchesById.has(task.reviewBatch)) errors.push(`${task.id} 的 Review Batch 不存在：${task.reviewBatch}`);
261     if (membership.get(task.id) !== task.reviewBatch) errors.push(`${task.id} 与 Review Batch 成员关系不一致。`);
262     const batch = batchesById.get(task.reviewBatch);
263     if (task.risk === "high" && batch && !batch.independentRequired) {
264       errors.push(`${task.id} 为高风险，Review Batch 必须要求独立复核。`);
265     }
266   }
267 
268   if (plan.mode === "multi") {
269     if (requireComplete && plan.tasks.length < 2) errors.push("multi 计划至少需要两个任务。" );
270     if (requireComplete && new Set(plan.tasks.map((task) => task.owner)).size < 2) errors.push("multi 计划至少需要两个不同所有者。" );
271     for (let leftIndex = 0; leftIndex < plan.tasks.length; leftIndex += 1) {
272       for (let rightIndex = leftIndex + 1; rightIndex < plan.tasks.length; rightIndex += 1) {
273         const left = plan.tasks[leftIndex];
274         const right = plan.tasks[rightIndex];
275         const ordered = dependencyReachable(tasksById, left.id, right.id) || dependencyReachable(tasksById, right.id, left.id);
276         if (!ordered && left.writeScopes.some((a) => right.writeScopes.some((b) => scopesOverlap(a, b)))) {
277           errors.push(`并行任务写入范围重叠：${left.id} 与 ${right.id}`);
278         }
279       }
280     }
281   }
282 
283   return [...new Set(errors)];
284 }
