139 function scopeValid(scope) {
140   if (typeof scope !== "string" || !scope.trim() || path.isAbsolute(scope)) return false;
141   const normalized = scope.replaceAll("\\", "/").replace(/^\.\//, "");
142   if (normalized === "." || normalized === "*" || normalized === "**" || normalized === "**/*") return false;
143   if (normalized === ".." || normalized.startsWith("../") || normalized.includes("/../")) return false;
144   return scopePrefix(normalized).length > 0;
